from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from django.conf import settings
from .models import BillingReceipt

class CustomerReceiptView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def get(self, request, receipt_id):
        # Strictly scope receipt retrieval to the requesting customer
        receipt = BillingReceipt.objects.filter(receipt_number=receipt_id, customer=request.user).first()
        if not receipt:
            return Response({'error': 'Receipt not found'}, status=status.HTTP_404_NOT_FOUND)

        response = Response({
            'receipt_number': receipt.receipt_number,
            'amount': str(receipt.amount),
            'billing_address': receipt.billing_address,
            'payment_last4': receipt.payment_last4
        })
        origin = request.headers.get('Origin')
        if origin in settings.CORS_ALLOWED_ORIGINS:
            response['Access-Control-Allow-Origin'] = origin
            response['Access-Control-Allow-Credentials'] = 'true'
        return response
